  "implementation": "def solve(case):
    try:
        min_cluster_size = case['min_cluster_size']
        clusters = case['clusters']
        parent = case['parent']
    except KeyError as e:
        raise ValueError(f"Missing required field: {e}")

    cluster_dict = {}
    for cl in clusters:
        cid = cl.get('cluster_id')
        if not cid or not isinstance(cid, str):
            raise ValueError('Invalid cluster_id')
        size = cl.get('size')
        if not isinstance(size, int) or size < 0:
            raise ValueError('size must be non-negative integer')
        birth = cl.get('birth_lambda')
        if not isinstance(birth, (int, float)):
            raise ValueError('birth_lambda must be a number')
        exits = cl.get('point_exit_lambdas')
        if not isinstance(exits, list) or not all(isinstance(x, (int, float)) for x in exits):
            raise ValueError('point_exit_lambdas must be a list of numbers')
        cluster_dict[cid] = cl

    for cid in cluster_dict:
        if cid not in parent:
            raise ValueError(f"Missing parent entry for {cid}")

    children = {cid: [] for cid in cluster_dict}
    for cid, p in parent.items():
        if p is not None:
            children[p].append(cid)

    retained_ids = {cid for cid, cl in cluster_dict.items() if cl['size'] >= min_cluster_size}

    def get_retained_ancestors(cid):
        ancestors = []
        cur = cid
        while True:
            p = parent.get(cur)
            if p is None or p not in retained_ids:
                break
            ancestors.append(p)
            cur = p
        return ancestors

    def get_retained_descendants(cid):
        descendants = []
        stack = [cid]
        while stack:
            node = stack.pop()
            for child in children.get(node, []):
                if child in retained_ids:
                    descendants.append(child)
                    stack.append(child)
        return descendants

    stability_list = []
    for cid in retained_ids:
        cl = cluster_dict[cid]
        birth = cl['birth_lambda']
        stab = sum(max(0, e - birth) for e in cl['point_exit_lambdas'])
        stability_list.append((-stab, cid, stab, cl))\
